    dt = DataType(
        "force_mags",
        np.ndarray,
        (Axis.NFRAMES, Axis.NATOMS, 3),
        required=False,
        deepmd_name="force_mag",
    )
    dpdata.System.register_data_type(dt)
    dpdata.LabeledSystem.register_data_type(dt)


